Fix by moving the checks to the preresume phase to support table
preloading. Also remove the unused function dm_cache_metadata_all_clean.

Fixes: 2ee57d587357 ("dm cache: add passthrough mode")
Signed-off-by: Ming-Hung Tsai <mtsai@redhat.com>
Signed-off-by: Mikulas Patocka <mpatocka@redhat.com>

Here is the root cause:
The dirty mapping check was performed during table creation (cache_create) using dm_cache_metadata_all_clean, assuming table reload occurs after suspension. However, LVM's table preload breaks this assumption and metadata updates can still be in progress, causing the check to incorrectly pass and allowing dirty mappings to be loaded into passthrough mode, leading to data loss.

Here is the patch:

 static int cache_create(struct cache_args *ca, struct cache **result)
 {
 	int r = 0;
 	char **error = &ca->ti->error;
 	struct cache *cache;
 	struct dm_target *ti = ca->ti;
 	dm_block_t origin_blocks;
 	struct dm_cache_metadata *cmd;
 	bool may_format = ca->features.mode == CM_WRITE;

 	cache = kzalloc_obj(*cache);
 	if (!cache)
 		return -ENOMEM;

 	cache->ti = ca->ti;
 	ti->private = cache;
 	ti->accounts_remapped_io = true;
 	ti->num_flush_bios = 2;
 	ti->flush_supported = true;

 	ti->num_discard_bios = 1;
 	ti->discards_supported = true;

 	ti->per_io_data_size = sizeof(struct per_bio_data);

 	cache->features = ca->features;
 	if (writethrough_mode(cache)) {
 		/* Create bioset for writethrough bios issued to origin */
 		r = bioset_init(&cache->bs, BIO_POOL_SIZE, 0, 0);
 		if (r)
 			goto bad;
 	}

 	cache->metadata_dev = ca->metadata_dev;
 	cache->origin_dev = ca->origin_dev;
 	cache->cache_dev = ca->cache_dev;

 	ca->metadata_dev = ca->origin_dev = ca->cache_dev = NULL;

 	origin_blocks = cache->origin_sectors = ti->len;
 	origin_blocks = block_div(origin_blocks, ca->block_size);
 	cache->origin_blocks = to_oblock(origin_blocks);

 	cache->sectors_per_block = ca->block_size;
 	if (dm_set_target_max_io_len(ti, cache->sectors_per_block)) {
 		r = -EINVAL;
 		goto bad;
 	}

 	if (ca->block_size & (ca->block_size - 1)) {
 		dm_block_t cache_size = ca->cache_sectors;

 		cache->sectors_per_block_shift = -1;
 		cache_size = block_div(cache_size, ca->block_size);
 		set_cache_size(cache, to_cblock(cache_size));
 	} else {
 		cache->sectors_per_block_shift = __ffs(ca->block_size);
 		set_cache_size(cache, to_cblock(ca->cache_sectors >> cache->sectors_per_block_shift));
 	}

 	r = create_cache_policy(cache, ca, error);
 	if (r)
 		goto bad;

 	cache->policy_nr_args = ca->policy_argc;
 	cache->migration_threshold = DEFAULT_MIGRATION_THRESHOLD;

 	r = set_config_values(cache, ca->policy_argc, ca->policy_argv);
 	if (r) {
 		*error = "Error setting cache policy's config values";
 		goto bad;
 	}

 	cmd = dm_cache_metadata_open(cache->metadata_dev->bdev,
 				     ca->block_size, may_format,
 				     dm_cache_policy_get_hint_size(cache->policy),
 				     ca->features.metadata_version);
 	if (IS_ERR(cmd)) {
 		*error = "Error creating metadata object";
 		r = PTR_ERR(cmd);
 		goto bad;
 	}
 	cache->cmd = cmd;
 	set_cache_mode(cache, CM_WRITE);
 	if (get_cache_mode(cache) != CM_WRITE) {
 		*error = "Unable to get write access to metadata, please check/repair metadata.";
 		r = -EINVAL;
 		goto bad;
 	}

-	if (passthrough_mode(cache)) {
-		bool all_clean;
-
-		r = dm_cache_metadata_all_clean(cache->cmd, &all_clean);
-		if (r) {
-			*error = "dm_cache_metadata_all_clean() failed";
-			goto bad;
-		}
-
-		if (!all_clean) {
-			*error = "Cannot enter passthrough mode unless all blocks are clean";
-			r = -EINVAL;
-			goto bad;
-		}
-
+	if (passthrough_mode(cache))
 		policy_allow_migrations(cache->policy, false);
-	}

 	spin_lock_init(&cache->lock);
 	bio_list_init(&cache->deferred_bios);
 	atomic_set(&cache->nr_allocated_migrations, 0);
 	atomic_set(&cache->nr_io_migrations, 0);
 	init_waitqueue_head(&cache->migration_wait);

 	r = -ENOMEM;
 	atomic_set(&cache->nr_dirty, 0);
 	cache->dirty_bitset = alloc_bitset(from_cblock(cache->cache_size));
 	if (!cache->dirty_bitset) {
 		*error = "could not allocate dirty bitset";
 		goto bad;
 	}
